import csv,json,os
from pathlib import Path
H=Path(__file__).resolve().parent;R=H.parents[3];PREP=R/'results/routeA/diagnostic_transient/diagnostic_attempt_001/preparation';OUT=PREP/'resource_revision_fix'

def calculate():
    old=json.loads((PREP/'resource_revision/capacity_accounting.json').read_text());free=json.loads((OUT/'start_guard.json').read_text())['free_bytes_at_start'];scratch=16*2**30;rows=[];series={}
