            rows.append({'Co':co,'category':cls,'during_run_bytes':'MEASURE_ACTUAL; R3+R4 jointly<=17179869184','post_seal_bytes':0,'purge_eligible_bytes_upper_bound':'MEASURE_SEALED_ALLOWLIST; shared joint cap above','permanent_bytes':0})
